script.setup:
// hsluv converts hue/saturation/lightness to sRGB so that equal lightness looks equally light.
// Left: plain HSL (computed in the shader). Right: HSLuv (or HPLuv) from the library, baked into a
// hue × saturation texture whenever the lightness changes. "Show lightness" turns both into grey L*.
const { Hsluv } = await ctx.utils.import("https://esm.sh/hsluv@1.0.2");
const gl = ctx.gl, tex = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, tex);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
// Labels under the wheels, drawn once on a small 2D canvas.
const label = new OffscreenCanvas(1024, 96), lc = label.getContext("2d");
lc.fillStyle = "#fff"; lc.font = "600 54px sans-serif"; lc.textAlign = "center"; lc.textBaseline = "middle";
const labelTex = gl.createTexture();
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_uv; uniform sampler2D u_label; uniform vec2 u_resolution; uniform float u_time;
uniform float u_light; uniform bool u_lum; uniform int u_swatches; uniform float u_spin;
const float PI = 3.14159265;
vec3 hsl(float h, float s, float l) {
  vec3 k = mod(vec3(0.0, 8.0, 4.0) + h * 12.0, 12.0);
  float a = s * min(l, 1.0 - l);
  return l - a * clamp(min(k - 3.0, 9.0 - k), -1.0, 1.0);
}
float lstar(vec3 c) {
  vec3 lin = mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c));
  float y = dot(lin, vec3(0.2126, 0.7152, 0.0722));
  float L = y > 0.008856 ? 116.0 * pow(y, 1.0 / 3.0) - 16.0 : 903.3 * y;
  return L / 100.0;
}
vec3 wheel(int side, float hue, float sat) {
  return side == 0 ? hsl(hue, sat, u_light / 100.0) : texture(u_uv, vec2(hue, sat * (100.0 / 101.0) + 0.5 / 101.0)).rgb;
}
void main() {
  float aspect = u_resolution.x / u_resolution.y;
  vec2 p = vec2(v_uv.x * aspect, v_uv.y);
  int side = v_uv.x < 0.5 ? 0 : 1;
  vec2 c = vec2(aspect * (side == 0 ? 0.26 : 0.74), 0.56);
  float R = min(0.3, aspect * 0.16);
  vec2 d = p - c; float r = length(d);
  float hue = fract(atan(d.y, d.x) / (2.0 * PI));
  vec3 col = vec3(0.08, 0.08, 0.09);
  if (r < R) col = wheel(side, hue, r / R);
  col = mix(col, vec3(0.08, 0.08, 0.09), smoothstep(R - 0.002, R + 0.002, r) * step(r, R + 0.01));
  // ring of evenly spaced swatches at full saturation
  float n = float(u_swatches), ringR = R + 0.065;
  float a0 = u_time * u_spin / 360.0;
  float k = floor((hue - a0) * n + 0.5);
  float sh = fract(a0 + k / n);
  vec2 sp = c + ringR * vec2(cos(sh * 2.0 * PI), sin(sh * 2.0 * PI));
  float dotR = min(0.035, PI * ringR / n * 0.8);
  float ds = length(p - sp);
  if (ds < dotR) col = wheel(side, sh, 1.0);
  col = mix(col, vec3(0.08, 0.08, 0.09), smoothstep(dotR - 0.003, dotR, ds) * step(ds, dotR + 0.004));
  if (u_lum) col = vec3(lstar(col));
  // labels
  vec2 lp = vec2(v_uv.x, (v_uv.y - 0.07) / 0.06);
  if (lp.y > 0.0 && lp.y < 1.0) col = mix(col, vec3(0.85), texture(u_label, vec2(lp.x, 1.0 - lp.y)).a);
  outColor = vec4(col, 1.0);
}`;
Object.assign(ctx.state, { Hsluv, tex, label, lc, labelTex, key: "", px: new Uint8Array(360 * 101 * 4),
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms;
const key = u.u_light + "|" + u.u_mode;
if (key !== s.key) {
  s.key = key;
  const c = new s.Hsluv(), pastel = u.u_mode === 1;
  for (let j = 0; j <= 100; j++) for (let i = 0; i < 360; i++) {
    if (pastel) { c.hpluv_h = i; c.hpluv_p = j; c.hpluv_l = u.u_light; c.hpluvToRgb(); }
    else { c.hsluv_h = i; c.hsluv_s = j; c.hsluv_l = u.u_light; c.hsluvToRgb(); }
    const o = (j * 360 + i) * 4;
    s.px[o] = Math.round(Math.min(1, Math.max(0, c.rgb_r)) * 255);
    s.px[o + 1] = Math.round(Math.min(1, Math.max(0, c.rgb_g)) * 255);
    s.px[o + 2] = Math.round(Math.min(1, Math.max(0, c.rgb_b)) * 255);
    s.px[o + 3] = 255;
  }
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.bindTexture(gl.TEXTURE_2D, s.tex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, 360, 101, 0, gl.RGBA, gl.UNSIGNED_BYTE, s.px);
  const { lc, label } = s;
  lc.clearRect(0, 0, label.width, label.height);
  lc.fillText("HSL", label.width * 0.26, label.height / 2);
  lc.fillText(pastel ? "HPLuv" : "HSLuv", label.width * 0.74, label.height / 2);
  gl.bindTexture(gl.TEXTURE_2D, s.labelTex);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, label);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
}
gl.useProgram(s.p);
ctx.utils.bindTexture(s.p, "u_uv", s.tex, 0);
ctx.utils.bindTexture(s.p, "u_label", s.labelTex, 1);
ctx.utils.drawFullscreen(s.p, { u_swatches: Math.max(3, u.u_swatches | 0) });
